from typing import Any, Dict, List, Tuple
from pydantic import BaseModel

class SecurityRequirement:
    def __init__(self, security_scheme, scopes):
        self.security_scheme = security_scheme
        self.scopes = scopes

class OAuth2Model(BaseModel):
    type: str = 'oauth2'
    flows: Dict[str, Any] = {}

class SecurityScheme:
    def __init__(self, scheme_name, model):
        self.scheme_name = scheme_name
        self.model = model

def jsonable_encoder(obj, **kwargs):
    # Simplified mock of jsonable_encoder
    if isinstance(obj, BaseModel):
        return obj.dict(by_alias=True, exclude_none=True)
    return obj

def get_openapi_security_definitions(security_requirements):
    security_definitions = {}
    operation_security = []
    for security_requirement in security_requirements:
        security_scheme = security_requirement.security_scheme
        security_name = security_scheme.scheme_name
        security_definition = jsonable_encoder(security_scheme.model)

        if security_name in security_definitions:
            existing_definition = security_definitions[security_name]
            if existing_definition.get('type') == 'oauth2' and security_definition.get('type') == 'oauth2':
                existing_flows = existing_definition.get('flows', {})
                new_flows = security_definition.get('flows', {})
                for flow_name, new_flow in new_flows.items():
                    if flow_name in existing_flows:
                        existing_flow = existing_flows[flow_name]
                        new_scopes = new_flow.get('scopes', {})
                        existing_scopes = existing_flow.get('scopes', {})
                        existing_scopes.update(new_scopes)
                        existing_flow['scopes'] = existing_scopes
                        for key, value in new_flow.items():
                            if key != 'scopes':
                                existing_flow[key] = value
                    else:
                        existing_flows[flow_name] = new_flow
                existing_definition['flows'] = existing_flows
            else:
                security_definitions[security_name] = security_definition
        else:
            security_definitions[security_name] = security_definition

        if security_definitions[security_name].get('type') == 'oauth2':
            flows = security_definitions[security_name].get('flows', {})
            for flow in flows.values():
                scopes = flow.get('scopes', {})
                for scope in security_requirement.scopes:
                    if scope not in scopes:
                        scopes[scope] = scope
                flow['scopes'] = scopes

        operation_security.append({security_name: security_requirement.scopes})
    return security_definitions, operation_security

# Test case 1: Same scheme, different operation scopes
model = OAuth2Model(flows={'password': {'tokenUrl': 'token', 'scopes': {}}})
scheme = SecurityScheme('my_scheme', model)
reqs = [
    SecurityRequirement(scheme, ['read']),
    SecurityRequirement(scheme, ['write']),
]
defs, ops = get_openapi_security_definitions(reqs)
print(f'Defs: {defs}')
print(f'Ops: {ops}')
assert defs['my_scheme']['flows']['password']['scopes'] == {'read': 'read', 'write': 'write'}

# Test case 2: Same scheme name, different models (flows)
model1 = OAuth2Model(flows={'password': {'tokenUrl': 'token1', 'scopes': {'read': 'read'}}})
model2 = OAuth2Model(flows={'password': {'tokenUrl': 'token2', 'scopes': {'write': 'write'}}})
scheme1 = SecurityScheme('my_scheme', model1)
scheme2 = SecurityScheme('my_scheme', model2)
reqs = [
    SecurityRequirement(scheme1, []),
    SecurityRequirement(scheme2, []),
]
defs, ops = get_openapi_security_definitions(reqs)
print(f'Defs: {defs}')
assert defs['my_scheme']['flows']['password']['scopes'] == {'read': 'read', 'write': 'write'}
assert defs['my_scheme']['flows']['password']['tokenUrl'] == 'token2'
"

